import{c as s,Q as t,j as n,m as e}from"./chunks/framework.DOi4mjdC.js";const k=JSON.parse('{"title":"SetVectorMask","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetVectorMask","slug":"setvectormask"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/掩码操作/SetVectorMask.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/掩码操作/SetVectorMask.md"}'),l={name:"api/SIMD-API/基础API/Memory矢量计算/掩码操作/SetVectorMask.md"};function p(c,a,o,d,r,i){return t(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="setvectormask" tabindex="-1">SetVectorMask <a class="header-anchor" href="#setvectormask" aria-label="Permalink to &quot;SetVectorMask&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>√</td></tr><tr><td>Kirin X90</td><td>√</td></tr><tr><td>Kirin 9030</td><td>√</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>用于在矢量计算时设置mask，使用前需要先调用<a href="./SetMaskCount.html">SetMaskCount</a>/<a href="./SetMaskNorm.html">SetMaskNorm</a>设置mask模式。在不同的模式下，mask的含义不同：</p><ul><li><p>Normal模式下，mask参数用来控制单次迭代内参与计算的元素个数。此时又可以划分为如下两种模式：</p><ul><li><p>连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]；当操作数为64位时，mask∈[1, 32]。</p></li><li><p>逐比特模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。分为maskHigh（高位mask）和maskLow（低位mask）。参数取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，maskLow、maskHigh∈[0, 264-1]，并且不同时为0；当操作数为32位时，maskHigh为0，maskLow∈(0, 264-1]；当操作数为64位时，maskHigh为0，maskLow∈(0, 232-1]。</p></li></ul></li><li><p>Counter模式下，mask参数表示整个矢量计算参与计算的元素个数。</p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>适用于Normal模式下mask逐比特模式和Counter模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, MaskMode mode = MaskMode::NORMAL&gt;</span></span>
<span class="line"><span>__aicore__ static inline void SetVectorMask(const uint64_t maskHigh, const uint64_t maskLow)</span></span></code></pre></div></li><li><p>适用于Normal模式下mask连续模式和Counter模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, MaskMode mode = MaskMode::NORMAL&gt;</span></span>
<span class="line"><span>__aicore__ static inline void SetVectorMask(int32_t len)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>矢量计算操作数数据类型。</td></tr><tr><td>mode</td><td>mask模式，MaskMode类型，定义如下：&lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1099210441167&quot;&gt;enum class MaskMode : uint8_t { NORMAL = 0, // Normal模式 COUNTER // Counter模式 };&lt;/pre&gt;</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>maskHigh</td><td>输入</td><td>Normal模式：对应Normal模式下的逐比特模式，可以按位控制哪些元素参与计算。传入高位mask值。 Counter模式：需要置0，本入参不生效。</td></tr><tr><td>maskLow</td><td>输入</td><td>Normal模式：对应Normal模式下的逐比特模式，可以按位控制哪些元素参与计算。传入低位mask值。 Counter模式：整个矢量计算过程中，参与计算的元素个数。</td></tr><tr><td>len</td><td>输入</td><td>Normal模式：对应Normal模式下的mask连续模式，表示单次迭代内表示前面连续的多少个元素参与计算。 Counter模式：整个矢量计算过程中，参与计算的元素个数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><p>该接口仅在矢量计算API的isSetMask模板参数为false时生效，使用完成后需要使用<a href="./ResetMask.html">ResetMask</a>将mask恢复为默认值。</p><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>可结合<a href="./SetMaskCount.html">SetMaskCount</a>与<a href="./SetMaskNorm.html">SetMaskNorm</a>使用，先设置mask的模式再设置mask：</p><ul><li><p>Normal模式调用示例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src0Local;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src1Local;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Normal模式</span></span>
<span class="line"><span>AscendC::SetMaskNorm();</span></span>
<span class="line"><span>AscendC::SetVectorMask&lt;half, AscendC::MaskMode::NORMAL&gt;(0xffffffffffffffff, 0xffffffffffffffff);  // 逐bit模式</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// SetVectorMask&lt;half, MaskMode::NORMAL&gt;(128);</span><span>  // 连续模式</span></span>
<span class="line"><span>// 多次调用矢量计算API, 可以统一设置为Normal模式，并设置mask参数，无需在API内部反复设置，省去了在API反复设置的过程，会有一定的性能优势</span></span>
<span class="line"><span>// dstBlkStride, src0BlkStride, src1BlkStride = 1, 单次迭代内数据连续读取和写入</span></span>
<span class="line"><span>// dstRepStride, src0RepStride, src1RepStride = 8, 相邻迭代间数据连续读取和写入</span></span>
<span class="line"><span>AscendC::Add&lt;half, false&gt;(dstLocal, src0Local, src1Local, AscendC::MASK_PLACEHOLDER, 1, { 2, 2, 2, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::Sub&lt;half, false&gt;(src0Local, dstLocal, src1Local, AscendC::MASK_PLACEHOLDER, 1, { 2, 2, 2, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::Mul&lt;half, false&gt;(src1Local, dstLocal, src0Local, AscendC::MASK_PLACEHOLDER, 1, { 2, 2, 2, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::ResetMask();</span></span></code></pre></div></li><li><p>Counter模式调用示例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Counter模式和tensor高维切分计算接口配合使用</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src0Local;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src1Local;</span></span>
<span class="line"><span>int32_t len = 128;  // 参与计算的元素个数</span></span>
<span class="line"><span>AscendC::SetMaskCount();</span></span>
<span class="line"><span>AscendC::SetVectorMask&lt;half, AscendC::MaskMode::COUNTER&gt;(len);</span></span>
<span class="line"><span>AscendC::Add&lt;half, false&gt;(dstLocal, src0Local, src1Local, AscendC::MASK_PLACEHOLDER, 1, { 1, 1, 1, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::Sub&lt;half, false&gt;(src0Local, dstLocal, src1Local, AscendC::MASK_PLACEHOLDER, 1, { 1, 1, 1, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::Mul&lt;half, false&gt;(src1Local, dstLocal, src0Local, AscendC::MASK_PLACEHOLDER, 1, { 1, 1, 1, 8, 8, 8 });</span></span>
<span class="line"><span>AscendC::SetMaskNorm();</span></span>
<span class="line"><span>AscendC::ResetMask();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Counter模式和tensor前n个数据计算接口配合使用</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; dstLocal;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;half&gt; src0Local;</span></span>
<span class="line"><span>half num = 2; </span></span>
<span class="line"><span>AscendC::SetMaskCount();</span></span>
<span class="line"><span>AscendC::SetVectorMask&lt;half, AscendC::MaskMode::COUNTER&gt;(128); // 参与计算的元素个数为128</span></span>
<span class="line"><span>AscendC::Adds&lt;half, false&gt;(dstLocal, src0Local, num, 1);</span></span>
<span class="line"><span>AscendC::Muls&lt;half, false&gt;(dstLocal, src0Local, num, 1);</span></span>
<span class="line"><span>AscendC::SetMaskNorm();</span></span>
<span class="line"><span>AscendC::ResetMask();</span></span></code></pre></div></li></ul>`,20)])])}const m=s(l,[["render",p]]);export{k as __pageData,m as default};
